-- ===========================================================
-- huellitas_base.sql — Base de datos de HUELLITAS (veterinaria)
-- Sistemas de Información Avanzada · UAE · 2026-2027 CII
-- Adaptada de sia_base.sql (agroservicio). Datos ficticios, ene–oct 2026.
-- -----------------------------------------------------------
-- XAMPP: cree primero una base llamada huellitas_base en phpMyAdmin,
-- selecciónela y use Importar con este archivo.
-- Hosting (AwardSpace): seleccione la base del panel, abra phpMyAdmin
-- e importe este archivo. NO contiene CREATE DATABASE ni USE.
-- OJO: borra y vuelve a crear todas las tablas.
-- Usuarios de prueba (cambie las contraseñas al publicar):
--   admin@huellitas.test        / Admin2026*  (administrador)
--   vendedor1@huellitas.test    / Sia2026*    (vendedor)
--   vendedor2@huellitas.test    / Sia2026*    (vendedor)
--   bodega@huellitas.test       / Sia2026*    (bodeguero)
--   veterinaria1@huellitas.test / Sia2026*    (veterinario)
--   veterinario2@huellitas.test / Sia2026*    (veterinario)
-- Tablas conservadas: categorias, proveedores, usuarios, clientes,
--   productos, compras, ventas, movimientos_stock.
-- Tablas nuevas: mascotas, servicios, citas, consultas.
-- ===========================================================

SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
SET time_zone = "-05:00";
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `consultas`, `citas`, `servicios`, `mascotas`, `movimientos_stock`, `ventas`, `compras`, `productos`, `categorias`, `clientes`, `proveedores`, `usuarios`;

CREATE TABLE `categorias` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nombre` varchar(100) NOT NULL,
  `descripcion` text DEFAULT NULL,
  `fecha_registro` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Dueños de las mascotas (se mantiene el nombre de tabla "clientes")
CREATE TABLE `clientes` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nombre` varchar(100) NOT NULL,
  `apellido` varchar(100) NOT NULL,
  `cedula` varchar(10) NOT NULL,
  `telefono` varchar(10) NOT NULL,
  `email` varchar(150) NOT NULL,
  `direccion` varchar(200) DEFAULT NULL,
  `fecha_registro` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `cedula` (`cedula`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `proveedores` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nombre_comercial` varchar(150) NOT NULL DEFAULT '',
  `nombre` varchar(150) NOT NULL,
  `telefono` varchar(10) NOT NULL,
  `email` varchar(150) DEFAULT NULL,
  `direccion` varchar(200) DEFAULT NULL,
  `fecha_registro` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `usuarios` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `cedula` varchar(10) NOT NULL DEFAULT '0000000000',
  `nombre` varchar(100) NOT NULL,
  `direccion` varchar(200) DEFAULT NULL,
  `email` varchar(150) NOT NULL,
  `telefono` varchar(10) NOT NULL DEFAULT '0000000000',
  `password` varchar(255) NOT NULL,
  `rol` varchar(20) NOT NULL DEFAULT 'vendedor',
  `es_admin` int(11) NOT NULL DEFAULT 0,
  `permisos` varchar(255) NOT NULL DEFAULT '',
  `estado` varchar(10) NOT NULL DEFAULT 'activo',
  `fecha_registro` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `productos` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nombre` varchar(150) NOT NULL,
  `id_categoria` int(11) NOT NULL,
  `descripcion` text DEFAULT NULL,
  `precio` decimal(10,2) NOT NULL,
  `unidad` varchar(50) NOT NULL,
  `fecha_registro` datetime DEFAULT current_timestamp(),
  `stock` int(11) NOT NULL DEFAULT 0,
  `especie` varchar(30) NOT NULL DEFAULT 'Todos',
  `fecha_vencimiento` date DEFAULT NULL,
  `stock_minimo` int(11) NOT NULL DEFAULT 5,
  PRIMARY KEY (`id`),
  KEY `id_categoria` (`id_categoria`),
  CONSTRAINT `productos_ibfk_1` FOREIGN KEY (`id_categoria`) REFERENCES `categorias` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- NUEVA: mascotas de cada dueño
CREATE TABLE `mascotas` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `id_cliente` int(11) NOT NULL,
  `nombre` varchar(80) NOT NULL,
  `especie` varchar(30) NOT NULL,
  `raza` varchar(80) DEFAULT NULL,
  `sexo` varchar(10) NOT NULL,
  `fecha_nacimiento` date DEFAULT NULL,
  `peso` decimal(5,2) DEFAULT NULL,
  `color` varchar(50) DEFAULT NULL,
  `esterilizado` tinyint(1) NOT NULL DEFAULT 0,
  `estado` varchar(10) NOT NULL DEFAULT 'activo',
  `fecha_registro` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `id_cliente` (`id_cliente`),
  CONSTRAINT `mascotas_ibfk_1` FOREIGN KEY (`id_cliente`) REFERENCES `clientes` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- NUEVA: catálogo de servicios de la veterinaria
CREATE TABLE `servicios` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nombre` varchar(100) NOT NULL,
  `descripcion` text DEFAULT NULL,
  `precio` decimal(10,2) NOT NULL,
  `duracion_min` int(11) NOT NULL DEFAULT 30,
  `estado` varchar(10) NOT NULL DEFAULT 'activo',
  `fecha_registro` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `compras` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `id_proveedor` int(11) NOT NULL,
  `id_producto` int(11) NOT NULL,
  `id_usuario` int(11) NOT NULL,
  `cantidad` int(11) NOT NULL,
  `precio_unitario` decimal(10,2) NOT NULL,
  `margen_ganancia` int(11) NOT NULL DEFAULT 30,
  `precio_venta` decimal(10,2) NOT NULL DEFAULT 0.00,
  `total` decimal(10,2) NOT NULL,
  `fecha_compra` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `id_proveedor` (`id_proveedor`),
  KEY `id_producto` (`id_producto`),
  KEY `id_usuario` (`id_usuario`),
  CONSTRAINT `compras_ibfk_1` FOREIGN KEY (`id_proveedor`) REFERENCES `proveedores` (`id`),
  CONSTRAINT `compras_ibfk_2` FOREIGN KEY (`id_producto`) REFERENCES `productos` (`id`),
  CONSTRAINT `compras_ibfk_3` FOREIGN KEY (`id_usuario`) REFERENCES `usuarios` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `ventas` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `id_cliente` int(11) NOT NULL,
  `id_producto` int(11) NOT NULL,
  `id_usuario` int(11) NOT NULL,
  `cantidad` int(11) NOT NULL,
  `precio_unitario` decimal(10,2) NOT NULL,
  `total` decimal(10,2) NOT NULL,
  `fecha_venta` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `id_producto` (`id_producto`),
  KEY `id_usuario` (`id_usuario`),
  KEY `ventas_cliente_fk` (`id_cliente`),
  CONSTRAINT `ventas_cliente_fk` FOREIGN KEY (`id_cliente`) REFERENCES `clientes` (`id`),
  CONSTRAINT `ventas_ibfk_1` FOREIGN KEY (`id_producto`) REFERENCES `productos` (`id`),
  CONSTRAINT `ventas_ibfk_2` FOREIGN KEY (`id_usuario`) REFERENCES `usuarios` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- NUEVA: citas agendadas (estado: pendiente, atendida, cancelada)
CREATE TABLE `citas` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `id_mascota` int(11) NOT NULL,
  `id_servicio` int(11) NOT NULL,
  `id_usuario` int(11) NOT NULL COMMENT 'veterinario asignado',
  `fecha_cita` datetime NOT NULL,
  `motivo` varchar(200) DEFAULT NULL,
  `estado` varchar(15) NOT NULL DEFAULT 'pendiente',
  `fecha_registro` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `id_mascota` (`id_mascota`),
  KEY `id_servicio` (`id_servicio`),
  KEY `id_usuario` (`id_usuario`),
  CONSTRAINT `citas_ibfk_1` FOREIGN KEY (`id_mascota`) REFERENCES `mascotas` (`id`),
  CONSTRAINT `citas_ibfk_2` FOREIGN KEY (`id_servicio`) REFERENCES `servicios` (`id`),
  CONSTRAINT `citas_ibfk_3` FOREIGN KEY (`id_usuario`) REFERENCES `usuarios` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- NUEVA: historial clínico (una consulta por cita atendida con servicio clínico)
CREATE TABLE `consultas` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `id_cita` int(11) NOT NULL,
  `id_mascota` int(11) NOT NULL,
  `id_usuario` int(11) NOT NULL,
  `fecha_consulta` datetime NOT NULL,
  `peso_kg` decimal(5,2) DEFAULT NULL,
  `temperatura` decimal(4,1) DEFAULT NULL,
  `diagnostico` varchar(255) NOT NULL,
  `tratamiento` text DEFAULT NULL,
  `proxima_revision` date DEFAULT NULL,
  `costo` decimal(10,2) NOT NULL DEFAULT 0.00,
  `fecha_registro` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `id_cita` (`id_cita`),
  KEY `id_mascota` (`id_mascota`),
  KEY `id_usuario` (`id_usuario`),
  CONSTRAINT `consultas_ibfk_1` FOREIGN KEY (`id_cita`) REFERENCES `citas` (`id`),
  CONSTRAINT `consultas_ibfk_2` FOREIGN KEY (`id_mascota`) REFERENCES `mascotas` (`id`),
  CONSTRAINT `consultas_ibfk_3` FOREIGN KEY (`id_usuario`) REFERENCES `usuarios` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `movimientos_stock` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `id_producto` int(11) NOT NULL,
  `tipo` varchar(10) NOT NULL,
  `cantidad` int(11) NOT NULL,
  `referencia` varchar(100) DEFAULT NULL,
  `fecha_movimiento` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `id_producto` (`id_producto`),
  CONSTRAINT `movimientos_stock_ibfk_1` FOREIGN KEY (`id_producto`) REFERENCES `productos` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

